def find_zero(xs: list):
    x = 0.0
    for _ in range(100):
        fx = poly(xs, x)
        if abs(fx) < 1e-7:
            return x
        dxs = [i * coeff for i, coeff in enumerate(xs)]
        dfx = poly(dxs, x)
        if dfx == 0:
            x += 0.1
        else:
            x -= fx / dfx
    return x
```

