def vowels_count(s):
    s_lower = s.lower()
    vowels = set('aeiou')
    count = 0
    length = len(s_lower)
    for i, char in enumerate(s_lower):
        if char in vowels:
            count += 1
        if char == 'y' and i == length - 1:
            count += 1
    return count
```

