def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == 0:
        return x == 0
    if n == -1:
        return x == 1 or x == -1

    if x == 0:
        return False

    temp_x = x
    while temp_x % n == 0:
        temp_x //= n
        if temp_x == 1:
            return True
    return temp_x == 1
```

